    let base = 800;
    match size {
        0 => 0,
        1 => base,
        2 => (base * 2 * 95) / 100,
        3 => (base * 3 * 90) / 100,
        4 => (base * 4 * 80) / 100,
        5 => (base * 5 * 75) / 100,
        _ => panic!("group size must be between 0 and 5"),
    }
}

pub fn lowest_price(books: &[u32]) -> u32 {
    // Count occurrences of each of the 5 possible book titles.
    let mut counts = [0u32; 5];
    for &b in books {
        if b >= 1 && b <= 5 {
            counts[(b - 1) as usize] += 1;
        }
    }

    // Greedily split the books into groups of distinct titles.
    let mut groups: Vec<u32> = Vec::new();
    loop {
        let distinct = counts.iter().filter(|&&c| c > 0).count();
        if distinct == 0 {
            break;
        }
        for c in counts.iter_mut() {
            if *c > 0 {
                *c -= 1;
            }
        }
        groups.push(distinct as u32);
    }

    // Optimization: a group of 5 plus a group of 3 costs more than
    // two groups of 4, so swap those combinations when present.
    loop {
        let has5 = groups.iter().position(|&g| g == 5);
        let has3 = groups.iter().position(|&g| g == 3);
        match (has5, has3) {
            (Some(i5), Some(i3)) => {
                // Replace one 5 and one 3 with two 4s.
                groups.retain({
                    let mut removed5 = false;
                    let mut removed3 = false;
                    move |&g| {
                        if g == 5 && !removed5 {
                            removed5 = true;
                            return false;
                        }
                        if g == 3 && !removed3 {
                            removed3 = true;
                            return false;
                        }
                        true
                    }
                });
                let _ = (i5, i3);
                groups.push(4);
                groups.push(4);
            }
            _ => break,
        }
    }

    groups.iter().map(|&g| group_price(g)).sum()
}
"}

